(()=>{'use strict';const show=(album,index)=>{const slides=[...album.querySelectorAll('[data-album-slide]')];if(!slides.length)return;index=(index+slides.length)%slides.length;album.dataset.albumIndex=index;slides.forEach((slide,i)=>{slide.hidden=i!==index;});album.querySelectorAll('[data-album-dot]').forEach((dot,i)=>{dot.setAttribute('aria-pressed',String(i===index));dot.classList.toggle('active',i===index);});};
function enhance(root=document){for(const album of root.querySelectorAll('[data-service-album]')){const slides=album.querySelectorAll('[data-album-slide]');let controls=album.querySelector('.service-album-controls');if(controls)controls.remove();if(slides.length>1){controls=document.createElement('div');controls.className='service-album-controls';for(const [step,label,glyph]of [[-1,'عکس قبلی','›'],[1,'عکس بعدی','‹']]){const button=document.createElement('button');button.type='button';button.dataset.albumStep=step;button.setAttribute('aria-label',label);button.textContent=glyph;controls.append(button);}const dots=document.createElement('div');dots.className='service-album-dots';dots.setAttribute('role','group');dots.setAttribute('aria-label','انتخاب تصویر');slides.forEach((_,i)=>{const button=document.createElement('button');button.type='button';button.dataset.albumDot=i;button.setAttribute('aria-label','نمایش تصویر '+(i+1));dots.append(button);});controls.append(dots);album.append(controls);}show(album,Number(album.dataset.albumIndex)||0);}}
document.addEventListener('click',event=>{const button=event.target.closest('[data-album-step],[data-album-dot]');if(!button)return;const album=button.closest('[data-service-album]');if(!album)return;event.preventDefault();show(album,button.hasAttribute('data-album-dot')?Number(button.dataset.albumDot):Number(album.dataset.albumIndex||0)+Number(button.dataset.albumStep));});
document.addEventListener('keydown',event=>{const album=event.target.closest('[data-service-album]');if(!album||!['ArrowLeft','ArrowRight'].includes(event.key)||event.target.isContentEditable)return;event.preventDefault();show(album,Number(album.dataset.albumIndex||0)+(event.key==='ArrowLeft'?1:-1));});window.PBEquipmentAlbum={enhance};enhance();})();
